'use strict';
const sourceRegistry=()=>catalog.source_registry||[];
function sourceCount(id){return all().filter(l=>l.advertiser_id===id).length}
function sourceDirectoryCard(s){const n=sourceCount(s.id);return `<article class="directory-card"><div class="directory-top"><span class="source-avatar">${esc(s.name.slice(0,1))}</span><span class="pill">${n?n+' ficha'+(n===1?'':'s'): 'Sin ficha cargada'}</span></div><h3>${esc(s.name)}</h3><p class="source-scope">${esc(s.scope)}</p>${s.address?`<p class="small">${esc(s.address)} · Jardín</p>`:''}<p class="small">${esc(s.note||'Anunciante identificado en la publicación. Disponibilidad pendiente.')}</p><div class="directory-links"><a href="${esc(safeUrl(s.url))}" target="_blank" rel="noopener">${s.kind==='local_directory'?'Ver contacto y procedencia':'Abrir publicación'} ↗</a>${s.official_url?`<a href="${esc(safeUrl(s.official_url))}" target="_blank" rel="noopener">Web de la inmobiliaria ↗</a>`:''}${s.phone?`<a href="tel:${esc(s.phone)}">${esc(s.phone)}</a>`:''}${n?`<button data-source-filter="${esc(s.id)}">Ver sus anuncios →</button>`:''}</div></article>`}
function showSourceDirectory(view='inventory'){const registry=sourceRegistry(),local=registry.filter(s=>s.kind==='local_directory'),active=registry.filter(s=>sourceCount(s.id)),social=registry.flatMap(s=>(s.socials||[]).map(p=>({...p,name:s.name})));const current=all(),identified=new Set(current.filter(l=>l.advertiser_identified).map(l=>l.advertiser_id)).size,unknown=current.filter(l=>!l.advertiser_identified).length;showModal('PROCEDENCIA DEL RADAR',`<div class="source-intro"><div class="eyebrow">MÁS VOCES. MEJOR CONTEXTO.</div><h2>El origen importa.</h2><p>Un mismo anunciante puede aparecer en varios portales. Aquí puedes distinguir quién anuncia y dónde se publicó.</p><div class="source-stats"><div><strong>${identified}</strong><span>Anunciantes identificados</span></div><div><strong>${unknown}</strong><span>Fichas con identidad pendiente</span></div><div><strong>${local.length}</strong><span>Contactos locales adicionales</span></div></div></div><nav class="source-tabs" aria-label="Tipo de fuente"><button data-directory-tab="inventory" class="${view==='inventory'?'selected':''}">Con anuncios</button><button data-directory-tab="local" class="${view==='local'?'selected':''}">Locales</button><button data-directory-tab="social" class="${view==='social'?'selected':''}">Redes</button></nav>${view==='social'?`<p class="notice">Perfiles enlazados desde la web de cada inmobiliaria. Instagram y Facebook limitaron la lectura pública: sus publicaciones no se incorporaron como anuncios verificados y no se rastrean automáticamente.</p><div class="directory-grid">${social.map(s=>`<article class="directory-card"><span class="eyebrow">${esc(s.platform)} · CONSULTA MANUAL</span><h3>${esc(s.name)}</h3><p class="small">${esc(s.note)}</p><div class="directory-links"><a href="${esc(safeUrl(s.url))}" target="_blank" rel="noopener">Abrir perfil ↗</a><a href="${esc(safeUrl(s.provenance_url))}" target="_blank" rel="noopener">Ver de dónde proviene el enlace ↗</a></div></article>`).join('')}</div>`:`<p class="notice">${view==='local'?'Contactos publicados en el directorio de Jardín. Se muestran como pistas para ampliar la búsqueda; aún no hay lotes individuales cargados de estos cinco contactos.':'La identidad comercial se toma del anuncio público. No acredita reputación, representación del propietario ni documentos legales del predio.'}</p><div class="directory-grid">${(view==='local'?local:active).map(sourceDirectoryCard).join('')}</div>`}<div class="sourcebox"><strong>Cómo evaluamos la procedencia</strong><p>Comprobamos que exista una publicación pública legible, datos concretos del inmueble y un anunciante o contacto rastreable cuando se publica. Conservamos fecha y enlace. La titularidad, las licencias y la disponibilidad se verifican aparte con documentos.</p><p class="small">${unknown} fichas de este municipio no tienen identidad comercial confirmada. No cuentan como anunciantes independientes.</p></div><button data-search-portals>Ampliar búsqueda en portales ↗</button>`)}
const portalSearch=sources;
sources=function(){showSourceDirectory()};$('#sourcesBtn').onclick=()=>sources();$('#showSourceStatus').onclick=()=>sources();
const renderBeforeSources=render;
render=function(){const select=$('#advertiser'),value=select.value;const entries=[...new Map(all().map(l=>[l.advertiser_id||'unidentified',l.advertiser||'Añadido por ti'])).entries()];select.innerHTML='<option value="">Todos los anunciantes</option>'+entries.map(([id,name])=>`<option value="${esc(id)}">${esc(name)}</option>`).join('');select.value=entries.some(([id])=>id===value)?value:'';renderBeforeSources();const items=all(),known=new Set(items.filter(l=>l.advertiser_identified).map(l=>l.advertiser_id)).size,main=items.filter(l=>l.advertiser_id==='miactivo').length;$('#sourceDiversity').innerHTML=`<div><span class="eyebrow">DIVERSIDAD DEL CATÁLOGO</span><strong>${known} anunciantes identificados · ${items.length} fichas</strong><p>${main?`MIACTIVO reúne ${main} de ${items.length} fichas (${Math.round(main/items.length*100)}%). `:''}${items.filter(l=>!l.advertiser_identified).length} tienen identidad pendiente.</p></div><button data-open-sources>Ver fuentes y redes ↗</button>`;if(catalog.diversity_update)$('#catalogNotice').textContent=`Catálogo ampliado: ${catalog.diversity_update.retained} fichas conservadas y ${catalog.diversity_update.added} nuevas. Precio y disponibilidad pendientes de confirmar. Las fotos proceden del anuncio y no acreditan el estado actual del predio.`};
const cardBeforeSources=card;
card=function(l){return cardBeforeSources(l).replace('<div class="cardactions">',`<div class="advertiser-line"><span>ANUNCIANTE</span><strong>${esc(l.advertiser||'Añadido por ti')}</strong></div><div class="cardactions">`)};
const detailBeforeSources=details;
details=function(id){detailBeforeSources(id);const l=lookupLot(id);if(!l)return;const box=document.createElement('section');box.className='sourcebox';box.innerHTML=`<strong>Anunciante: ${esc(l.advertiser||'Añadido por ti')}</strong><p class="small">Publicado en ${esc(l.source)}. ${l.advertiser_identified?'Nombre comercial visible en la publicación; identidad jurídica sin verificar.':'Identidad del anunciante pendiente. No se cuenta como fuente independiente confirmada.'}</p>${l.published_at?`<p class="small">Fecha de publicación indicada: ${esc(l.published_at)}. Consultado: ${esc(dateCO(l.observed_at))}.</p>`:''}${l.external_photo_album?`<a href="${esc(safeUrl(l.external_photo_album))}" target="_blank" rel="noopener">Álbum enlazado en el anuncio ↗</a><p class="small">${esc(l.photo_note)}</p>`:''}${l.geo_note?`<p class="small">${esc(l.geo_note)}</p>`:''}`;$('#propertyContent').after(box)};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.directoryTab)showSourceDirectory(b.dataset.directoryTab);if(b.dataset.sourceFilter){$('#advertiser').value=b.dataset.sourceFilter;$('#modal').close();navigate('discover');$('#sourceDiversity').scrollIntoView({behavior:'smooth',block:'start'})}if(b.hasAttribute('data-search-portals'))portalSearch()});
$('#resetFilters').addEventListener('click',()=>{$('#advertiser').value='';render()});
render();
